import{_ as a}from"./chunks/01_full_ui.DLwPHa0J.js";import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"桌面端文档","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/index.md","filePath":"desktop/index.md","lastUpdated":1784192334000}'),l={name:"desktop/index.md"};function d(n,e,c,s,h,u){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="桌面端文档" tabindex="-1">桌面端文档 <a class="header-anchor" href="#桌面端文档" aria-label="Permalink to &quot;桌面端文档&quot;">​</a></h1><blockquote><p>图形化的 AI Code Editor，支持多会话、多标签、IM 接入的完整桌面体验。</p></blockquote><p><img src="'+a+'" alt="桌面端界面"></p><hr><h2 id="文档目录" tabindex="-1">文档目录 <a class="header-anchor" href="#文档目录" aria-label="Permalink to &quot;文档目录&quot;">​</a></h2><h3 id="快速上手" tabindex="-1"><a href="./01-quick-start">快速上手</a> <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;[快速上手](./01-quick-start.md)&quot;">​</a></h3><p>面向用户的桌面端使用指南：界面布局、对话操作、多标签、权限控制、项目管理、模型配置、IM 适配器、定时任务。</p><h3 id="架构设计" tabindex="-1"><a href="./02-architecture">架构设计</a> <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;[架构设计](./02-architecture.md)&quot;">​</a></h3><p>面向开发者的技术架构：三层架构（Electron Host → Server → CLI）、WebSocket 协议、HTTP API、状态管理、协议代理、适配器桥接、目录结构。</p><h3 id="功能详解" tabindex="-1"><a href="./03-features">功能详解</a> <a class="header-anchor" href="#功能详解" aria-label="Permalink to &quot;[功能详解](./03-features.md)&quot;">​</a></h3><p>深入每个功能模块：聊天引擎、代码展示、工具调用、Agent Teams、提供商管理、技能/Agent、定时任务、IM 适配器、Session Trace、设计系统。</p><h3 id="安装指南" tabindex="-1"><a href="./04-installation">安装指南</a> <a class="header-anchor" href="#安装指南" aria-label="Permalink to &quot;[安装指南](./04-installation.md)&quot;">​</a></h3><p>下载安装、macOS/Windows 常见问题、Web UI 模式。</p><h3 id="h5-访问" tabindex="-1"><a href="./06-h5-access">H5 访问</a> <a class="header-anchor" href="#h5-访问" aria-label="Permalink to &quot;[H5 访问](./06-h5-access.md)&quot;">​</a></h3><p>面向个人和团队的可选浏览器访问：开启 H5、生成 Token、配置允许来源、通过局域网或反向代理在手机上访问聊天界面。</p><h3 id="移动端-android-客户端" tabindex="-1"><a href="/mobile/">移动端 Android 客户端</a> <a class="header-anchor" href="#移动端-android-客户端" aria-label="Permalink to &quot;[移动端 Android 客户端](/mobile/)&quot;">​</a></h3><p>通过原生 Android 壳层扫码连接桌面端 H5 服务，在手机 WebView 中继续聊天、审批权限、上传文件和接收流式响应。</p><h3 id="tauri-迁移-electron-调研索引" tabindex="-1"><a href="./07-electron-migration-research">Tauri 迁移 Electron 调研索引</a> <a class="header-anchor" href="#tauri-迁移-electron-调研索引" aria-label="Permalink to &quot;[Tauri 迁移 Electron 调研索引](./07-electron-migration-research.md)&quot;">​</a></h3><p>桌面端从 Tauri 2 迁移到 Electron 的系统能力盘点、React 复用边界、目标架构、安全要求和迁移路径。</p><h3 id="electron-迁移任务清单" tabindex="-1"><a href="./08-electron-migration-tasks">Electron 迁移任务清单</a> <a class="header-anchor" href="#electron-迁移任务清单" aria-label="Permalink to &quot;[Electron 迁移任务清单](./08-electron-migration-tasks.md)&quot;">​</a></h3><p>逐阶段执行清单：host adapter、Electron main/preload、系统能力、build/release、跨平台 smoke 和 Computer Use 验收。</p><h3 id="electron-迁移验证清单" tabindex="-1"><a href="./09-electron-migration-validation-checklist">Electron 迁移验证清单</a> <a class="header-anchor" href="#electron-迁移验证清单" aria-label="Permalink to &quot;[Electron 迁移验证清单](./09-electron-migration-validation-checklist.md)&quot;">​</a></h3><p>迁移收口验证：自动化证据、Review 收口项、macOS Computer Use smoke、Windows/Linux 实机验收边界。</p><h3 id="electron-发布与自动更新" tabindex="-1"><a href="./10-release-auto-update">Electron 发布与自动更新</a> <a class="header-anchor" href="#electron-发布与自动更新" aria-label="Permalink to &quot;[Electron 发布与自动更新](./10-release-auto-update.md)&quot;">​</a></h3><p>了解应用内更新、各平台安装包和常见更新问题。</p><h3 id="electron-迁移交互式验收清单" tabindex="-1"><a href="/desktop/electron-migration-qa-checklist.html">Electron 迁移交互式验收清单</a> <a class="header-anchor" href="#electron-迁移交互式验收清单" aria-label="Permalink to &quot;[Electron 迁移交互式验收清单](/desktop/electron-migration-qa-checklist.html)&quot;">​</a></h3><p>本地浏览器可直接打开的验收 checklist，支持勾选进度、记录问题、导出 Markdown。</p><hr><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><h3 id="用户" tabindex="-1">用户 <a class="header-anchor" href="#用户" aria-label="Permalink to &quot;用户&quot;">​</a></h3><ol><li>阅读 <a href="./04-installation">安装指南</a> 下载安装</li><li>阅读 <a href="./01-quick-start">快速上手</a> 了解界面和操作</li><li>配置 AI 模型提供商，开始对话</li></ol><h3 id="开发者" tabindex="-1">开发者 <a class="header-anchor" href="#开发者" aria-label="Permalink to &quot;开发者&quot;">​</a></h3><ol><li>阅读 <a href="./02-architecture">架构设计</a> 理解三层架构</li><li>关键源码位置： <ul><li><code>desktop/src/</code> — React 前端</li><li><code>desktop/electron/</code> — Electron main/preload/系统能力 host</li><li><code>desktop/src-tauri/</code> — 历史资源目录，当前仅作为 sidecar、图标和 preview agent 的 Electron 打包输入</li><li><code>desktop/sidecars/</code> — Sidecar 入口</li><li><code>src/server/</code> — Express API 服务端</li><li><code>adapters/</code> — IM 适配器</li></ul></li></ol><hr><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td><strong>Electron Host</strong></td><td>跨平台桌面壳层，管理窗口、系统能力、Sidecar 进程和更新</td></tr><tr><td><strong>Sidecar</strong></td><td>随主进程启动的后台服务，运行 API 服务器</td></tr><tr><td><strong>Session</strong></td><td>一次对话会话，绑定工作目录，通过 WebSocket 通信</td></tr><tr><td><strong>Tab</strong></td><td>标签页，对应一个 Session 或特殊页面</td></tr><tr><td><strong>Provider</strong></td><td>AI 模型提供商，支持 Anthropic/OpenAI 兼容接口</td></tr><tr><td><strong>Adapter</strong></td><td>IM 适配器，支持 Telegram / 飞书 / WhatsApp / 微信 / 钉钉接入</td></tr><tr><td><strong>H5 Token</strong></td><td>移动端浏览器或 Android 客户端连接桌面服务时使用的远程访问凭据</td></tr><tr><td><strong>Store</strong></td><td>Zustand 状态容器，按领域拆分管理</td></tr></tbody></table>',36)])])}const k=t(l,[["render",d]]);export{b as __pageData,k as default};
